ByteAddressBuffer input_0 : register(t0);
ByteAddressBuffer input_1 : register(t1);
RWByteAddressBuffer output_0 : register(u0);

#define TOTAL 67108864
#define THREADS 256

[numthreads(THREADS, 1, 1)]
void main(uint3 dtid : SV_DispatchThreadID)
{
    uint idx = dtid.x * 16;
    uint4 a = input_0.Load4(idx);
    uint4 b = input_1.Load4(idx);

    half2 a0 = (half2)f16tof32(uint2(a.x & 0xFFFF, (a.x >> 16) & 0xFFFF));
    half2 a1 = (half2)f16tof32(uint2(a.y & 0xFFFF, (a.y >> 16) & 0xFFFF));
    half2 a2 = (half2)f16tof32(uint2(a.z & 0xFFFF, (a.z >> 16) & 0xFFFF));
    half2 a3 = (half2)f16tof32(uint2(a.w & 0xFFFF, (a.w >> 16) & 0xFFFF));

    half2 b0 = (half2)f16tof32(uint2(b.x & 0xFFFF, (b.x >> 16) & 0xFFFF));
    half2 b1 = (half2)f16tof32(uint2(b.y & 0xFFFF, (b.y >> 16) & 0xFFFF));
    half2 b2 = (half2)f16tof32(uint2(b.z & 0xFFFF, (b.z >> 16) & 0xFFFF));
    half2 b3 = (half2)f16tof32(uint2(b.w & 0xFFFF, (b.w >> 16) & 0xFFFF));

    half2 c0 = a0 + b0;
    half2 c1 = a1 + b1;
    half2 c2 = a2 + b2;
    half2 c3 = a3 + b3;

    uint4 r;
    uint2 p0 = f32tof16((float2)c0);
    uint2 p1 = f32tof16((float2)c1);
    uint2 p2 = f32tof16((float2)c2);
    uint2 p3 = f32tof16((float2)c3);
    r.x = (p0.x & 0xFFFF) | (p0.y << 16);
    r.y = (p1.x & 0xFFFF) | (p1.y << 16);
    r.z = (p2.x & 0xFFFF) | (p2.y << 16);
    r.w = (p3.x & 0xFFFF) | (p3.y << 16);
    output_0.Store4(idx, r);
}
